                if p.field_len != 0 || p.state == State::InQuotedField {
                    p.save_field();
                    return Some(Ok(p.fields));
                }
                return None;
            };
            for c in line.chars() {
                if let Err(e) = p.process(Some(c)) {
                    self.pos = self.text.len();
                    return Some(Err(e));
                }
            }
            if let Err(e) = p.process(None) {
                self.pos = self.text.len();
                return Some(Err(e));
            }
            if p.state == State::StartRecord {
                return Some(Ok(p.fields));
            }
        }
    }
}

