    /// `"키"` 공백 `:` 공백 까지 읽는다.
    fn key(&mut self) -> Result<Vec<u8>, Invalid> {
        if self.peek() != Some(b'"') {
            return Err(Invalid);
        }
        let key = self.string()?;
        self.ws();
        self.expect(b':')?;
