//! 최상위 객체의 멤버만 값으로 만들고, 그 안쪽 배열·객체는 명시적 스택으로 문법만 검사한다(재귀 없음).

/// Python 3.12.3 에서 측정한 중첩 한도(바깥 객체 포함). 계약 2.2절, verify/probe.py.
pub const MAX_DEPTH: usize = 9997;
/// `sys.get_int_max_str_digits()` 기본값.
pub const MAX_INT_DIGITS: usize = 4300;

#[derive(Debug, PartialEq, Eq)]
pub struct Invalid;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    /// 정수. i64 범위를 넘으면 None(이 프로그램의 모든 범위 검사에서 범위 밖)
    Int(Option<i64>),
    Float(f64),
    /// WTF-8 바이트(짝 없는 서로게이트도 3바이트로 담는다)
    Str(Vec<u8>),
    /// 배열 또는 객체(내용은 쓰지 않는다)
    Container,
}

#[derive(Debug, PartialEq)]
pub enum Parsed {
    /// 멤버를 나온 순서대로 담는다. 같은 키는 뒤의 것이 이기므로 찾을 때 뒤에서부터 본다.
    Object(Vec<(Vec<u8>, Value)>),
    NotObject,
}

pub fn get<'a>(members: &'a [(Vec<u8>, Value)], key: &str) -> Option<&'a Value> {
    members
        .iter()
        .rev()
        .find(|(k, _)| k == key.as_bytes())
        .map(|(_, v)| v)
}

pub fn loads(text: &str) -> Result<Parsed, Invalid> {
    if text.starts_with('\u{feff}') {
        return Err(Invalid);
    }
    let mut p = Parser {
        b: text.as_bytes(),
        i: 0,
    };
    p.ws();
    let parsed = match p.peek() {
        Some(b'{') => Parsed::Object(p.top_object()?),
        Some(b'[') => {
            p.skip_container(0)?;
            Parsed::NotObject
        }
        _ => {
            p.scalar()?;
            Parsed::NotObject
        }
    };
    p.ws();
    if p.i != p.b.len() {
        return Err(Invalid);
    }
    Ok(parsed)
}

struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

fn push_wtf8(out: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push(0xC0 | (cp >> 6) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    } else if cp < 0x10000 {
        out.push(0xE0 | (cp >> 12) as u8);
        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    } else {
        out.push(0xF0 | (cp >> 18) as u8);
        out.push(0x80 | ((cp >> 12) & 0x3F) as u8);
        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    }
}

