            ("2026-01-01T00:00:00-23:59", Some("2026-01-01T23:59:00+00:00")),
            ("2026-01-01T00:00:00+24:00", None),
            ("2026-01-01T00:00:00+00:99", Some("2025-12-31T22:21:00+00:00")),
            ("2026-01-01T24:00:00Z", None),
            ("2026-01-01T23:59:60Z", None),
            ("0000-01-01T00:00:00Z", None),
            ("2024-02-29T00:00:00Z", Some("2024-02-29T00:00:00+00:00")),
            ("2100-02-29T00:00:00Z", None),
            ("9999-12-31T23:59:59-00:01", None),
            ("0001-01-01T00:00:00+00:01", None),
            ("0001-01-01T00:00:00-00:01", Some("0001-01-01T00:01:00+00:00")),
            ("2026-01-01T00:00:00.1234Z", Some("2026-01-01T00:00:00.123400+00:00")),
            ("2026-01-01T00:00:00-00:00", Some("2026-01-01T00:00:00+00:00")),
            ("9999-12-31T23:59:59.999999Z", Some("9999-12-31T23:59:59.999999+00:00")),
            ("2026-01-01T00:00:00.1234567Z", None),
            ("2026-01-01T00:00:00.Z", None),
            ("2026-01-01T00:00:00", None),
            ("2026-01-01T00:00:00+0100", None),
            ("2026-01-01 00:00:00Z", None),
        ];
        for (input, want) in cases {
            assert_eq!(iso(input).as_deref(), want, "{input}");
        }
    }

