        out.extend_from_slice(
            format!(
                ",\"count\":{},\"error_rate\":\"{}\",\"p50\":{},\"p95\":{}}}",
                t.count,
                t.error_rate,
                py_repr(t.p50),
                py_repr(t.p95)
            )
            .as_bytes(),
        );
    }
    out.extend_from_slice(b"]}\n");
    out
}

/// 입출력 없는 본체. (종료 코드, stdout, stderr)
pub fn run(text: &str, fmt: Format, top_n: u64, as_json: bool, strict: bool) -> (i32, Vec<u8>, Vec<u8>) {
    let rows = match fmt {
        Format::Csv => {
            // 파일 끝까지 읽은 뒤에 헤더·긴 필드 오류를 먼저 본다(--strict 의 앞선 잘못된 레코드보다 우선)
            let (rows, header_error) = record::read_csv(text);
            if let Some(err) = header_error {
                return (EXIT_INPUT_ERROR, Vec::new(), format!("logstat: error: {err}\n").into_bytes());
            }
            rows
        }
        Format::Jsonl => record::read_jsonl(text),
    };
    let mut records = Vec::new();
    let mut skipped = 0;
    for (number, item) in rows {
        match item {
            Ok(r) => records.push(r),
            Err(reason) => {
                if strict {
                    return (
                        EXIT_INPUT_ERROR,
                        Vec::new(),
                        format!("logstat: error: record {number}: {reason}\n").into_bytes(),
                    );
                }
                skipped += 1;
            }
        }
    }
    let summary = summarize(&records, skipped, top_n);
    let out = if as_json {
        format_json(&summary)
    } else {
        format_text(&summary)
    };
    (EXIT_OK, out, Vec::new())
}

